export const SAMPLE = {"main.tex":"\\documentclass[11pt]{article}\n\\usepackage[margin=1.1in]{geometry}\n\\usepackage{amsmath,amssymb,amsthm}\n\\usepackage{natbib}\n\\usepackage{booktabs}\n\\usepackage{hyperref}\n\n\\newtheorem{proposition}{Proposition}\n\\newtheorem{lemma}[proposition]{Lemma}\n\\theoremstyle{definition}\n\\newtheorem{definition}{Definition}\n\n\\newcommand{\\R}{\\mathbb{R}}\n\\newcommand{\\E}{\\mathbb{E}}\n\\DeclareMathOperator*{\\argmax}{arg\\,max}\n\\newcommand{\\key}[1]{\\texttt{#1}}\n\n\\title{Editing in Print}\n\\author{Rikuy\\thanks{A typeset editor for \\LaTeX{} sources. Everything on this page is live.}}\n\\date{\\today}\n\n\\begin{document}\n\\maketitle\n\n\\begin{abstract}\nYou are reading a \\LaTeX{} document that you can edit where it stands. Click into any sentence and type. Each keystroke becomes a minimal patch to the source, so the \\texttt{.tex} file stays yours: no import, no export, no lock in.\n\\end{abstract}\n\n\\section{How to use it}\nClick anywhere in this paragraph and start typing. Select a phrase and press \\key{Ctrl+B} to make it \\textbf{bold} or \\key{Ctrl+I} to \\emph{emphasise} it. Press \\key{Enter} for a new paragraph. Typing a percent sign gives you 50\\%, not a comment, because Rikuy escapes special characters for you.\n\nMath is an object on the page. Click $\\alpha + \\beta = \\gamma$ to edit its source with a live preview, or type a dollar sign to insert new math. Display equations work the same way, numbers and all:\n\\begin{equation}\n  V(k) = \\max_{c \\in [0,k]} \\bigl\\{ u(c) + \\beta\\, V\\bigl(f(k) - c\\bigr) \\bigr\\}. \\label{eq:bellman}\n\\end{equation}\nReferences follow their targets: equation~\\eqref{eq:bellman} renumbers itself if you add an equation above it.\n\n\\section{The round trip}\\label{sec:roundtrip}\nThe page and the source never disagree, because the page is computed from the source and every edit is computed back into it.\n\n\\begin{definition}[Source map]\nA \\emph{source map} assigns to every visible character on the page the exact span of source text that produced it.\n\\end{definition}\n\n\\begin{proposition}[Minimal patches]\\label{prop:patch}\nIf an edit only touches characters inside one source map span, the patch changes only that span. Markup outside the selection is never rewritten.\n\\end{proposition}\n\n\\begin{proof}\nRikuy never regenerates the file. Insertions are escaped and placed at the mapped offset; deletions that would cut through markup fall back to removing only the visible characters, which leaves every brace balanced.\n\\end{proof}\n\nProposition~\\ref{prop:patch} is why your diffs stay small:\\footnote{Try it: edit this footnote, then look at the source pane.} the history of a paper edited here reads like one edited by hand.\n\n\\section{Citations and cross references}\nCitations come from the bibliography file in this project. \\citet{knuth1984} designed \\TeX{} around a source language, and \\citet{lamport1994} built \\LaTeX{} on top of it. Editing the typeset output directly is an old idea \\citep{kastrup2002, wen2018}, usually defeated by the gap between source and print. Section~\\ref{sec:roundtrip} explains how Rikuy closes it.\n\\begin{align}\n  \\E[\\,y \\mid x\\,] &= \\int_{\\R} y \\, f(y \\mid x)\\, dy \\label{eq:cond}\\\\\n  \\hat\\theta &= \\argmax_{\\theta \\in \\Theta} \\sum_{i=1}^{n} \\log f(y_i \\mid x_i; \\theta) \\label{eq:mle}\n\\end{align}\nBoth rows of the alignment above carry their own numbers, (\\ref{eq:cond}) and (\\ref{eq:mle}).\n\n\\section{Keyboard}\nTable~\\ref{tab:keys} lists the shortcuts. Every cell is editable.\n\n\\begin{table}[h]\n\\centering\n\\begin{tabular}{ll}\n\\toprule\nKeys & Action \\\\\n\\midrule\nCtrl+B, Ctrl+I & Bold, emphasis \\\\\nCtrl+M or \\$ & New inline math \\\\\n\\textbackslash & Insert a command \\\\\nCtrl+Z, Ctrl+Shift+Z & Undo, redo \\\\\nAlt+click & Show in source \\\\\n\\bottomrule\n\\end{tabular}\n\\caption{Shortcuts. On a Mac, use Cmd for Ctrl.}\\label{tab:keys}\n\\end{table}\n\n\\section{The exact PDF}\nThe pages you edit are typeset by the browser, so their line and page breaks are close to \\TeX{} but not identical: the browser breaks lines one at a time, while \\TeX{} chooses the breaks for a whole paragraph at once \\citep{knuthplass1981}. The PDF button runs the real thing: pdf\\LaTeX{} from \\TeX{} Live 2026, compiled to WebAssembly and running in this browser. Its PDF is the one \\texttt{pdflatex} would give you, it recompiles a moment after each edit, and a click on it finds the same sentence here. Packages that draw, such as TikZ, show as source blocks on these pages and fully drawn in the PDF.\n\n\\begin{itemize}\n  \\item Open a \\texttt{.tex}, a \\texttt{.bib}, or an Overleaf \\texttt{.zip}.\n  \\item Save downloads the whole project as a \\texttt{.zip}.\n  \\item Your work is kept in this browser between visits.\n\\end{itemize}\n\n\\bibliographystyle{plainnat}\n\\bibliography{refs}\n\\end{document}\n","refs.bib":"@book{knuth1984,\n  author    = {Knuth, Donald E.},\n  title     = {The {\\TeX}book},\n  publisher = {Addison-Wesley},\n  address   = {Reading, MA},\n  year      = {1984}\n}\n\n@book{lamport1994,\n  author    = {Lamport, Leslie},\n  title     = {{\\LaTeX}: A Document Preparation System},\n  edition   = {2nd},\n  publisher = {Addison-Wesley},\n  address   = {Reading, MA},\n  year      = {1994}\n}\n\n@article{knuthplass1981,\n  author  = {Knuth, Donald E. and Plass, Michael F.},\n  title   = {Breaking Paragraphs into Lines},\n  journal = {Software: Practice and Experience},\n  volume  = {11},\n  number  = {11},\n  pages   = {1119--1184},\n  year    = {1981}\n}\n\n@article{kastrup2002,\n  author  = {Kastrup, David},\n  title   = {Revisiting {WYSIWYG} Paradigms for Authoring {\\LaTeX}},\n  journal = {TUGboat},\n  volume  = {23},\n  number  = {1},\n  year    = {2002}\n}\n\n@inproceedings{wen2018,\n  author    = {Wen, Elliott and Weber, Gerald},\n  title     = {{SwiftLaTeX}: Exploring Web-Based True {WYSIWYG} Editing for Digital Publishing},\n  booktitle = {Proceedings of the ACM Symposium on Document Engineering},\n  year      = {2018}\n}\n"};
